            .magic = HEAP_MAGIC,
            .version = HEAP_VERSION,
            .flags = 0,
            .pool_uuid_low = uuid_low,
            .pool_uuid_high = uuid_high,
            .endianness = if (builtin.cpu.arch.endian() == .little) Endianness.little else Endianness.big,
